-- PostgreSQL (relational) — main tables used by matching. Generated by JPA in the real project.
CREATE TABLE users (
    id            BIGSERIAL PRIMARY KEY,
    email         VARCHAR(255) NOT NULL UNIQUE,
    password_hash VARCHAR(255) NOT NULL,
    user_type     VARCHAR(10)  NOT NULL CHECK (user_type IN ('ERASMUS', 'LOCAL')),
    status        VARCHAR(25)  NOT NULL
);

CREATE TABLE interests (
    id       BIGSERIAL PRIMARY KEY,
    name     VARCHAR(255) NOT NULL UNIQUE,
    category VARCHAR(20)  NOT NULL
);

CREATE TABLE profiles (
    id           BIGSERIAL PRIMARY KEY,
    user_id      BIGINT NOT NULL UNIQUE REFERENCES users(id) ON DELETE CASCADE,  -- right to be forgotten
    display_name VARCHAR(50) NOT NULL,
    gender       VARCHAR(10),
    completed    BOOLEAN NOT NULL DEFAULT FALSE
);

CREATE TABLE profile_interests (                       -- many-to-many with referential integrity
    profiles_id  BIGINT NOT NULL REFERENCES profiles(id) ON DELETE CASCADE,
    interests_id BIGINT NOT NULL REFERENCES interests(id),
    PRIMARY KEY (profiles_id, interests_id)
);

CREATE TABLE profile_spoken_languages (
    profile_id    BIGINT NOT NULL REFERENCES profiles(id) ON DELETE CASCADE,
    language_code CHAR(2) NOT NULL,
    level         VARCHAR(2) NOT NULL
);

CREATE TABLE match_requests (
    id           BIGSERIAL PRIMARY KEY,
    sender_id    BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    receiver_id  BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    status       VARCHAR(10) NOT NULL,
    created_at   TIMESTAMPTZ NOT NULL,
    responded_at TIMESTAMPTZ
);
CREATE INDEX idx_match_requests_users ON match_requests (sender_id, receiver_id, status);
